import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import './StorePage.css';

const StorePage = () => {
  const { user, updateUserBalance } = useAuth();
  const navigate = useNavigate();
  const [games, setGames] = useState([]);
  const [cart, setCart] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    loadGames();
    loadCart();
  }, []);

  const loadGames = async () => {
    try {
      const response = await api.get('/games');
      setGames(response.data);
    } catch (error) {
      console.error('Ошибка загрузки игр:', error);
    } finally {
      setLoading(false);
    }
  };

  const loadCart = () => {
    const savedCart = localStorage.getItem('cart');
    if (savedCart) {
      setCart(JSON.parse(savedCart));
    }
  };

  const addToCart = (game) => {
    if (!cart.find(item => item.id === game.id)) {
      const newCart = [...cart, game];
      setCart(newCart);
      localStorage.setItem('cart', JSON.stringify(newCart));
    }
  };

  const removeFromCart = (gameId) => {
    const newCart = cart.filter(item => item.id !== gameId);
    setCart(newCart);
    localStorage.setItem('cart', JSON.stringify(newCart));
  };

  const purchaseGame = async (gameId) => {
    try {
      const response = await api.post(`/store/purchase/${gameId}`);
      alert(response.data.message);
      updateUserBalance(response.data.newBalance);
      loadGames();
    } catch (error) {
      alert(error.response?.data || 'Ошибка покупки');
    }
  };

  const checkoutCart = async () => {
    if (cart.length === 0) return;

    const gameIds = cart.map(item => item.id);
    
    try {
      const response = await api.post('/store/cart/checkout', gameIds);
      alert(response.data.message);
      updateUserBalance(response.data.newBalance);
      setCart([]);
      localStorage.removeItem('cart');
      loadGames();
    } catch (error) {
      alert(error.response?.data || 'Ошибка оформления заказа');
    }
  };

  const cartTotal = cart.reduce((sum, item) => sum + item.price, 0);

  const filteredGames = games.filter(game => {
    const matchesFilter = filter === 'all' || game.genre === filter;
    const matchesSearch = game.title.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesFilter && matchesSearch;
  });

  const genres = ['all', ...new Set(games.map(g => g.genre))];

  if (loading) return <div className="loading">Загрузка...</div>;

  return (
    <div className="store-page">
      <div className="store-header">
        <h1>🛒 Магазин игр</h1>
        <div className="user-balance">
          💰 Баланс: <strong>{user?.balance?.toFixed(2) || 0} ₽</strong>
          <button onClick={() => navigate('/topup')} className="btn-topup-small">
            Пополнить
          </button>
        </div>
      </div>

      <div className="store-controls">
        <input
          type="text"
          placeholder="🔍 Поиск игр..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="search-input"
        />
        
        <div className="genre-filters">
          {genres.map(genre => (
            <button
              key={genre}
              className={`genre-btn ${filter === genre ? 'active' : ''}`}
              onClick={() => setFilter(genre)}
            >
              {genre === 'all' ? 'Все' : genre}
            </button>
          ))}
        </div>
      </div>

      <div className="store-content">
        <div className="games-grid">
          {filteredGames.map(game => {
            const isInCart = cart.find(item => item.id === game.id);
            const isOwned = user?.ownedGames?.some(og => og.id === game.id);
            
            return (
              <div key={game.id} className="game-card">
                <img src={game.imageUrl} alt={game.title} />
                <div className="game-info">
                  <h3>{game.title}</h3>
                  <p className="game-genre">{game.genre}</p>
                  <p className="game-price">{game.price.toFixed(2)} ₽</p>
                  
                  {isOwned ? (
                    <button className="btn-owned" disabled>
                      ✓ В библиотеке
                    </button>
                  ) : isInCart ? (
                    <button
                      className="btn-in-cart"
                      onClick={() => removeFromCart(game.id)}
                    >
                      Убрать из корзины
                    </button>
                  ) : (
                    <>
                      <button
                        className="btn-buy-now"
                        onClick={() => purchaseGame(game.id)}
                      >
                        Купить сейчас
                      </button>
                      <button
                        className="btn-add-cart"
                        onClick={() => addToCart(game)}
                      >
                        В корзину
                      </button>
                    </>
                  )}
                </div>
              </div>
            );
          })}
        </div>

        {cart.length > 0 && (
          <div className="cart-sidebar">
            <h2>🛒 Корзина ({cart.length})</h2>
            <div className="cart-items">
              {cart.map(item => (
                <div key={item.id} className="cart-item">
                  <span className="cart-item-name">{item.title}</span>
                  <span className="cart-item-price">{item.price.toFixed(2)} ₽</span>
                  <button
                    className="btn-remove"
                    onClick={() => removeFromCart(item.id)}
                  >
                    ✕
                  </button>
                </div>
              ))}
            </div>
            <div className="cart-total">
              <strong>Итого: {cartTotal.toFixed(2)} ₽</strong>
            </div>
            <button
              className="btn-checkout"
              onClick={checkoutCart}
              disabled={user?.balance < cartTotal}
            >
              {user?.balance < cartTotal 
                ? `Недостаточно средств (нужно ${cartTotal} ₽)` 
                : 'Оформить покупку'}
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default StorePage;
